UPDATE public.armour_pieces p
SET max_rarity = m.max_rarity
FROM (SELECT armour_piece_id, MAX(rarity) AS max_rarity FROM public.armour_piece_upgrades
      WHERE armour_piece_id IN ('210001301', '210001302', '210001303', '210001304', '210001305') GROUP BY armour_piece_id) m
WHERE p.id = m.armour_piece_id;

UPDATE public.armour_pieces p
SET skills = u.skills
FROM public.armour_piece_upgrades u
WHERE u.armour_piece_id = p.id AND u.rarity = p.max_rarity AND p.id IN ('210001301', '210001302', '210001303', '210001304', '210001305');

COMMIT;
